// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

interface ITroveManager {
    enum Status {
        nonExistent,
        active,
        closedByOwner,
        closedByLiquidation,
        closedByRedemption
    }

    function getTroveStatus(address _borrower) external view returns (Status);
    function getTroveColl(address _borrower) external view returns (uint256);
    function getTroveDebt(address _borrower) external view returns (uint256);
    function getTrovePrincipal(address _borrower) external view returns (uint256);
    function getTroveInterestOwed(address _borrower) external view returns (uint256);
    function getCurrentICR(address _borrower, uint256 _price) external view returns (uint256);
    function getNominalICR(address _borrower) external view returns (uint256);
    function getTCR(uint256 _price) external view returns (uint256);
    function checkRecoveryMode(uint256 _price) external view returns (bool);
    function getEntireSystemColl() external view returns (uint256);
    function getEntireSystemDebt() external view returns (uint256);
    function getTroveOwnersCount() external view returns (uint256);
    function getEntireDebtAndColl(address _borrower) external view returns (
        uint256 coll,
        uint256 principal,
        uint256 interest,
        uint256 pendingCollateral,
        uint256 pendingPrincipal,
        uint256 pendingInterest
    );
    function MCR() external view returns (uint256);
    function CCR() external view returns (uint256);
}

